<script>
var V='stats',D=null,ST=null,RANGE=7,$=function(i){return document.getElementById(i)};
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function when(t){var d=new Date(t*1000);return d.toLocaleDateString('en-GB',{day:'numeric',month:'short'})+' · '+d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}
// what happened since the owner last opened this dashboard (last-open time kept on this phone); own devices are never counted
var SINCE=null,SEEN=0,TD=null,DEVS=null;
(function(){var K='fk_adm_seen';try{SEEN=+localStorage.getItem(K)||0}catch(e){}
  fetch('api.php?a=since&t='+SEEN,{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){if(!j||j.error)return;SINCE=j;if(V==='stats')draw();try{localStorage.setItem(K,String(j.now))}catch(e){}}).catch(function(){})})();
