var SRC={site:'SMR website banner',wa:'WhatsApp',ig:'Instagram',fb:'Facebook',tt:'TikTok',sc:'Snapchat',x:'X / Twitter',google:'Google search',direct:'Direct / typed / WhatsApp',other:'Other websites',qr:'QR code'};
