 var c=[[j.new_players,'brand-new players','first game ever',1],[j.players,'players'],[j.returning,'came back'],[j.visits,'visits'],[j.best,'best score'],[Math.round(j.avg),'average score'],[j.shares,'shares'],[j.recs,'places recommended',0,j.recs>0],[j.home,'played from home screen']];
 return '<div class="since"><div class="hd">Since you last checked <span>'+esc(at)+'</span></div><div class="big">'+n(j.games)+'<small>new game'+(j.games===1?'':'s')+'</small></div>'+(j.games||j.visits?'<div class="g">'+c.map(function(x){return '<div'+(x[3]?' class="hl"':'')+'><b>'+(typeof x[0]==='number'?n(x[0]):x[0])+'</b><small>'+x[1]+'</small></div>'}).join('')+'</div>':'<p class="none">Nothing new yet. Your own phones are never counted.</p>')+'</div>'}
function todayBox(){if(!TD)return '<div class="secT">Today</div><p class="mut">Loading…</p>';var p=TD.events.play||{n:0,u:0};
 return '<div class="secT">Today</div><div class="kp kp3">'+[[n(p.n),'Games'],[n(p.u),'Players'],[n(TD.new),'New people'],[n(TD.opens),'Visits'],[TD.best,'Best score'],[n((TD.events.share||{n:0}).n),'Shares']].map(function(k){return '<div class="k"><b>'+k[0]+'</b><small>'+k[1]+'</small></div>'}).join('')+'</div>'}
function drawStats(){var top=sinceBox()+todayBox()+'<div class="secT">More</div><div class="rng">'+[[7,'This week'],[30,'This month'],[0,'All time']].map(function(r){return '<button data-r="'+r[0]+'" class="'+(RANGE===r[0]?'on':'')+'">'+r[1]+'</button>'}).join('')+'</div>';
 if(!ST){return top+'<p class="empty">Loading…</p>'}
 var pl=ev('play'),vi=ev('visit'),h=top+'<div style="display:none">'+[[1,'Today'],[7,'7 days'],[30,'30 days'],[0,'All time']].map(function(r){return '<button data-r="'+r[0]+'" class="'+(RANGE===r[0]?'on':'')+'">'+r[1]+'</button>'}).join('')+'</div>';
 h+='<h3 style="margin-top:0">Visitors</h3><div class="kp">'+[[n(ST.opens),'Total opens','every time the link was opened'],[n(ST.unique),'Unique people','different phones/computers'],[n(ST.new),'New people','first time ever in this period'],[n(ST.returning),'Returning people','opened it on 2+ different days'],[n(Math.max(0,ST.opens-ST.unique)),'Repeat opens','opens by people who already came'],[(ST.unique?(ST.opens/ST.unique).toFixed(1):0),'Opens per person','on average']].map(function(k){return '<div class="k"><b>'+k[0]+'</b><small>'+k[1]+'</small><em>'+k[2]+'</em></div>'}).join('')+'</div><h3>Playing</h3>';
 h+='<div class="kp">'+[[n(pl.n),'Games played',(pl.u?(pl.n/pl.u).toFixed(1):0)+' games per player'],[n(pl.u),'People who played',(ST.unique?Math.round(100*pl.u/ST.unique):0)+'% of visitors'],[ST.best,'Best score','average '+ST.avg],[n(ev('share').n),'Shares',n(ev('card').n)+' score cards made'],[n(ST.app_users),'Playing from home screen',n(ev('hs_open').n)+' opened the how-to'],[n(ev('smr').n),'Clicked through to SMR Digital','from the game footer']].map(function(k){return '<div class="k"><b>'+k[0]+'</b><small>'+k[1]+'</small><em>'+k[2]+'</em></div>'}).join('')+'</div>';
 h+='<h3>Where people came from</h3>'+bars(ST.sources,function(r){return SRC[r.src]||r.src||'Unknown'},'u');
