 +'<div class="fld bmi"'+(bm==='image'?'':' hidden')+'><label>Picture</label>'+(c.banner_v?'<img id="sBp" src="api.php?a=banner&v='+c.banner_v+'" style="display:block;width:100%;max-height:150px;object-fit:contain;border-radius:8px;background:#fff;margin-bottom:8px">':'<p class="mut" id="sBp0">No picture yet.</p>')+'<input type="file" id="sBf" accept="image/*"><small>Any shape works: it always fills the width and the screen makes room for its height. JPG or PNG. It uploads as soon as you pick it.</small><p class="ok" id="sBu"></p></div>'
 +'<div class="fld bmx"'+(bm==='off'?' hidden':'')+'><label>Link when tapped (optional)</label><input type="url" id="sBl" maxlength="300" placeholder="https://instagram.com/..." value="'+esc(c.banner_link||'')+'"></div>'
 +'<div class="fld bmx"'+(bm==='off'?' hidden':'')+'><label>Where</label>'+opt('sBw',bw,[['both','Both'],['home','Home screen'],['over','End screen']])+'</div>'
 +'<h3>Game</h3>'
 +'<label class="tg">Show the leaderboard<input type="checkbox" id="sLb"'+(c.show_leaderboard?' checked':'')+'></label>'
 +'<label class="tg">Show "Recommend a place"<input type="checkbox" id="sRec"'+(c.show_recommend?' checked':'')+'></label>'
