 +(ST&&ST.season?'<div class="tip" style="margin:8px 0">🍂 <b>Trees in the game now:</b> '+esc(ST.season.now_text)+(ST.season.next?'<br>Next: '+esc(ST.season.next_text)+' from <b>'+esc(ST.season.next_at)+'</b>. You get a notification when it changes.':'')+'</div>':'')
 +'<a class="lk" href="/flappy/?panel=1" target="_blank" style="display:inline-block;margin:4px 0 2px">Open the preview ›</a><small style="display:block">Opens the game with a small panel: pick any time of day, weather and season and see it straight away. Only you see it; players always get the real time, weather and season.</small>'
 +'<div class="fld" style="margin-top:12px"><label>Difficulty</label><div class="opts" id="sDiff">'+['easy','normal','hard'].map(function(d){return '<button data-d="'+d+'" class="'+(c.difficulty===d?'on':'')+'">'+d[0].toUpperCase()+d.slice(1)+'</button>'}).join('')+'</div><small>Easy = wider gaps between pipes. Changes for everyone within a few minutes.</small></div>'
 +'<button class="save" id="sSave">Save settings</button><p class="ok" id="sOk"></p>'
 +'<h3>Your devices</h3><p class="mut" style="margin:0 0 10px">Your own phones are left out of every number. Any phone you play on while logged in to SMR Admin is spotted by itself; tick any other phone or tablet of yours here (the one at the top is usually the one you just played on).</p><div id="devs">'+drawDevs()+'</div>'
 +'<div class="tip">Game link: <code>smrgraphics.co.uk/flappykabootar</code> · <a class="lk" href="/flappy/" target="_blank">Open the game</a></div>'}

var DEVN={iphone:'iPhone',ipad:'iPad',android:'Android phone',desktop:'Computer',other:'Device'};
function drawDevs(){if(!DEVS){api('devices').then(function(j){DEVS=j.devices;var d=$('devs');if(d)d.innerHTML=drawDevs()});return '<p class="mut">Loading…</p>'}
 if(!DEVS.length)return '<p class="mut">No devices yet.</p>';
 return DEVS.map(function(d){return '<div class="dv'+(d.mine?' me':'')+'"><div class="i"><b>'+(DEVN[d.dev]||'Device')+(d.app?' · home screen app':'')+'</b><small>Last played '+when(d.last)+' · '+n(d.games)+' game'+(d.games===1?'':'s')+(d.best?' · best '+d.best:'')+' · ID '+esc(d.id)+'</small></div><button data-own="'+esc(d.vid)+'" data-on="'+(d.mine?0:1)+'">'+(d.mine?'✓ Mine':'This is me')+'</button></div>'}).join('')}
function carsHtml(){var h='';var cs=D.cars||[];h+='<h2>Car requests'+(cs.filter(function(c){return c.status==0}).length?' ('+cs.filter(function(c){return c.status==0}).length+' new)':'')+'</h2><p class="mut">Players in Flappy Kabootar and Jummah Dash send their first name, car and a photo. Make the game car (or use their phone\'s quick cut-out), then Approve: their photo is deleted, the car drives through everyone\'s game, and their phone gets a message (it shows in the game, and as a notification if they turned them on). On their own phone it comes past every 30 seconds.</p>';
 if(!cs.length)return h+'<p class="empty">No car requests yet.</p>';
 cs.forEach(function(c){var fl=c.flag==='front'?'Not a side view':c.flag==='crop'?'Not the whole car':'',gm=c.game==='jd'?'Jummah Dash':'Flappy Kabootar',st=c.status==1?'<span class="live">In the game</span>':c.status==2?'<span class="warn">Not used</span>':'<span class="newb">New</span>';
  h+='<div class="card carq'+(c.status==2?' done':'')+'"><b>'+esc(c.model)+'</b> '+st+(fl&&c.status==0?' <span class="warn">'+fl+'</span>':'')+'<div class="tm">'+esc(c.name||'')+' &middot; '+gm+' &middot; '+when(c.at)+(c.notif>0?' &middot; &#128276; notifications on':'')+'</div><div class="cimgs">';
  if(c.photo)h+='<a href="api.php?a=carphoto&id='+c.id+'" target="_blank" class="carimg"><img src="api.php?a=carphoto&id='+c.id+'" alt=""><small>Their photo (tap for full size)</small></a>';
  if(c.cut)h+='<div class="carimg"><img src="api.php?a=carphoto&id='+c.id+'&k=cut" alt=""><small>Quick cut-out from their phone</small></div>';
  if(c.final)h+='<div class="carimg"><img src="api.php?a=carimg&id='+c.id+'&v='+(c.done_at||c.at)+'" alt=""><small>Game car</small></div>';
  h+='</div><div class="row">';
  if(c.status!=1){h+='<label class="upl">Upload finished car<input type="file" accept="image/png,image/jpeg" data-cup="'+c.id+'" hidden></label>';if(c.cut)h+='<button data-cok="'+c.id+'" data-cut="1">Approve with the quick cut-out</button>';if(c.final&&!c.cut)h+='<button data-cok="'+c.id+'">Approve</button>'}
  else h+='<button data-cok="'+c.id+'" data-u="1">Take it out of the game</button>';
  h+='<button data-cmsg="'+c.id+'">Message</button>'+(c.status==0?'<button data-cno="'+c.id+'">Not suitable</button>':'')+'<button data-cdel="'+c.id+'">Delete</button></div>';
  h+='<div class="cmbox hide" id="cmb'+c.id+'"><textarea id="cmt'+c.id+'" maxlength="400" placeholder="Your message to '+esc(c.name||'them')+' (shows on their phone)"></textarea><div class="row"><button data-csend="'+c.id+'">Send message</button></div></div></div>'});return h}
document.addEventListener('change',function(e){var f=e.target;if(!f.dataset||!f.dataset.cup||!f.files||!f.files[0])return;var r=new FileReader();r.onload=function(){api('car_ok',{id:+f.dataset.cup,img:r.result}).then(load).catch(function(x){alert(x.message)})};r.readAsDataURL(f.files[0])});
function load(){api('admin').then(function(j){D=j;draw();try{parent.postMessage({fkNew:j.new},location.origin)}catch(e){}$('nb').textContent=j.new||''}).catch(function(e){$('v').innerHTML='<p class="empty">'+esc(e.message)+'</p>'})}
function draw(){var h='';if(V==='stats'){$('v').innerHTML=drawStats();return}if(V==='set'){$('v').innerHTML=drawSet();return}if(!D)return;
 if(V==='inbox'){h=(D.fests&&D.fests.length?'<h2>Coming up</h2><p class="mut">Special days for the game. Nothing changes by itself: you get a notification 2 weeks and 3 days before, then ask Claude to decorate the game.</p>'+D.fests.map(function(f){var soon=f.days<=14;return '<div class="card fest'+(soon?' soon':'')+'"><b>'+esc(f.name)+'</b> <span class="mut">'+esc(f.date)+' · '+(f.days<=0?'today':f.days===1?'tomorrow':'in '+f.days+' days')+(f.moon?' · date depends on the moon':'')+'</span><p>'+esc(f.idea)+'</p></div>'}).join(''):'')+carsHtml()+'<h2>Places to feature'+(D.new?' <span class="pill">'+D.new+' new</span>':'')+'</h2><p class="mut">Sent from the "Recommend a Luton place" button in the game.</p>';
  if(!D.recs.length)h+='<p class="empty">No recommendations yet.</p>';
  D.recs.forEach(function(r){var q=encodeURIComponent(r.name+' '+(r.address||'')+' Luton');h+='<div class="card'+(r.done?' done':'')+'"><b>'+esc(r.name)+'</b>'+(r.address?'<div class="ad">'+esc(r.address)+'</div>':'')+(r.note?'<div class="nt">'+esc(r.note)+'</div>':'')+'<div class="tm">'+when(r.at)+'</div><div class="row"><a href="https://www.google.com/maps/search/?api=1&query='+q+'" target="_blank" rel="noopener">Map</a><button data-done="'+r.id+'" data-u="'+(r.done?1:0)+'">'+(r.done?'Mark new':'Done')+'</button><button data-del="'+r.id+'">Delete</button></div></div>'});}
 else{var tb=function(rows,t){var s='<h2>'+t+'</h2><div class="card"><table class="lb">';if(!rows.length)s+='<tr><td colspan="3" class="empty">No scores yet.</td></tr>';rows.forEach(function(r,i){s+='<tr><td>'+(i+1)+'</td><td>'+esc(r.name)+'<div class="tm" style="margin:0">'+when(r.at)+(r.phone?' &middot; <a href="tel:'+esc(r.phone)+'">&#128222; '+esc(r.phone.slice(0,5)+' '+r.phone.slice(5))+'</a> <a href="https://wa.me/44'+esc(r.phone.slice(1))+'" target="_blank">WhatsApp</a>':'')+'</div></td><td class="s">'+r.score+'</td><td style="width:26px"><button title="Remove" data-sd="'+r.id+'">&times;</button></td></tr>'});return s+'</table></div>'};
  var fl=D.flags||[],fh='';if(fl.length){fh='<h2>Scores to check ('+fl.length+')</h2><p class="mut">These came in faster than the game allows. Add them if you know they are real.</p>';fl.forEach(function(f){var mm=function(x){return x<0?'not timed':Math.floor(x/60)+'m '+(x%60)+'s'};fh+='<div class="card"><b>'+esc(f.name)+' &middot; '+f.score+'</b><div class="tm">'+when(f.at)+' &middot; played '+mm(f.took)+', needs at least '+mm(f.need)+'</div><div class="row"><button data-fok="'+f.id+'">Add to leaderboard</button><button data-fdel="'+f.id+'">Ignore</button></div></div>'})}
  var add='<button id="asOpen" class="addbtn">+ Add a name &amp; score</button><div class="card addsc hide" id="asBox"><input id="asN" maxlength="14" placeholder="Name"><input id="asS" type="number" min="1" max="9999" placeholder="Score"><select id="asD"><option value="">Today</option><option value="old">Earlier (all-time only)</option></select><button id="asB">Add to leaderboard</button><div id="asE" class="tm"></div></div>';
  var rn=D.runs||[],rh='';if(rn.length){rh='<h2>Best games played</h2><p class="mut">Every game is counted, even if no name was saved. Tap Add to put one on the leaderboard.</p><div class="card"><table class="lb">';rn.forEach(function(r,i){rh+='<tr><td>'+(i+1)+'</td><td>'+when(r.at)+'<div class="tm" style="margin:0">'+esc(r.dev||'')+(r.src?' &middot; '+esc(r.src):'')+(+r.app?' &middot; home screen':'')+(r.place?' &middot; ended at '+esc(r.place):'')+'</div></td><td class="s">'+r.score+'</td><td>'+(+r.saved?'<span class="tm">saved</span>':'<button data-addrun="'+r.score+'">Add</button>')+'</td></tr>'});rh+='</table></div>'}
  h=add+fh+tb(D.today,'Today')+tb(D.all,'All time')+rh+'<p class="mut">'+D.entries+' names entered so far. Tap &times; to remove a rude name or a fake score.</p><p class="mut"><a class="lk" href="/flappy/" target="_blank">Open the game</a></p>';}
 $('v').innerHTML=h}
document.addEventListener('change',function(e){if(e.target.id!=='sBf'||!e.target.files[0])return;var f=e.target.files[0],u=$('sBu');u.textContent='Uploading…';
 var img=new Image();img.onload=function(){var w=Math.min(1600,img.naturalWidth),hh=Math.round(img.naturalHeight*w/img.naturalWidth),cv=document.createElement('canvas');cv.width=w;cv.height=hh;var cx=cv.getContext('2d');cx.drawImage(img,0,0,w,hh);
  var png=/png|gif|webp/.test(f.type),data=cv.toDataURL(png?'image/png':'image/jpeg',.9);if(png&&data.length>2800000)data=cv.toDataURL('image/jpeg',.88);
  api('banner_up',{data:data}).then(function(j){if(j&&j.error){u.textContent=j.error;return}ST.settings=j.settings;u.textContent='Uploaded. Tap Save settings if you changed anything else.';var p=$('sBp')||document.createElement('img');p.id='sBp';p.src='api.php?a=banner&v='+j.settings.banner_v;p.style.cssText='display:block;width:100%;max-height:150px;object-fit:contain;border-radius:8px;background:#fff;margin-bottom:8px';if(!p.parentNode){var z=$('sBp0');z.parentNode.replaceChild(p,z)}}).catch(function(er){u.textContent=er.message||'Upload failed.'})};
 img.onerror=function(){u.textContent="That file isn't a picture we can use."};img.src=URL.createObjectURL(f)});
document.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;
 if(b.id==='asOpen'){$('asBox').classList.toggle('hide');if(!$('asBox').classList.contains('hide'))$('asN').focus();return}
 if(b.dataset.addrun){$('asBox').classList.remove('hide');$('asS').value=b.dataset.addrun;$('asN').focus();$('asN').scrollIntoView({block:'center'});return}
 if(b.dataset.fok){api('flag_ok',{id:+b.dataset.fok}).then(load);return}
 if(b.dataset.fdel){api('flag_del',{id:+b.dataset.fdel}).then(load);return}
 if(b.id==='asB'){var nm=$('asN').value.trim(),sc=+$('asS').value,d=$('asD').value;if(!nm||!(sc>=1&&sc<=9999)){$('asE').textContent='Add a name and a score from 1 to 9999.';return}
  var dy='';if(d==='old'){var x=new Date(Date.now()-86400000*2);dy=x.toISOString().slice(0,10)}
  b.disabled=true;api('score_add',{name:nm,score:sc,day:dy}).then(function(j){b.disabled=false;if(j&&j.error){$('asE').textContent=j.error;return}load()});return}
 if(b.dataset.v){V=b.dataset.v;document.querySelectorAll('.seg button').forEach(function(x){x.classList.toggle('on',x===b)});draw();return}
 if(b.dataset.own){b.disabled=true;api('owner',{vid:b.dataset.own,on:b.dataset.on==='1'}).then(function(j){DEVS=j.devices;$('devs').innerHTML=drawDevs();SINCE=null;loadToday();loadStats();fetch('api.php?a=since&t='+SEEN,{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(x){SINCE=x;draw()})});return}
 if(b.dataset.r!=null){RANGE=+b.dataset.r;ST=null;draw();loadStats();return}
 if(b.dataset.d){document.querySelectorAll('#sDiff button').forEach(function(x){x.classList.toggle('on',x===b)});return}
 if(b.closest&&b.closest('#sBm')){document.querySelectorAll('#sBm button').forEach(function(x){x.classList.toggle('on',x===b)});var v=b.dataset.v;document.querySelector('.bmt').hidden=v!=='text';document.querySelector('.bmi').hidden=v!=='image';document.querySelectorAll('.bmx').forEach(function(x){x.hidden=v==='off'});return}
 if(b.closest&&b.closest('#sBw')){document.querySelectorAll('#sBw button').forEach(function(x){x.classList.toggle('on',x===b)});return}
 if(b.id==='sSave'){var d=document.querySelector('#sDiff .on'),bmb=document.querySelector('#sBm .on'),bwb=document.querySelector('#sBw .on');api('settings_save',{banner_mode:bmb?bmb.dataset.v:'off',banner_text:$('sBt').value,banner_link:$('sBl').value,banner_where:bwb?bwb.dataset.v:'both',show_leaderboard:$('sLb').checked,show_recommend:$('sRec').checked,sky_live:$('sSky').checked,wx_live:$('sWx').checked,difficulty:d?d.dataset.d:'normal'}).then(function(j){ST.settings=j.settings;$('sOk').textContent='Saved. The game picks it up within a few minutes.'}).catch(function(e){$('sOk').textContent=e.message});return}
 if(b.dataset.cok)return api('car_ok',{id:+b.dataset.cok,undo:b.dataset.u==='1',use_cut:b.dataset.cut==='1'}).then(load).catch(function(e){alert(e.message)});
 if(b.dataset.cmsg){var bx=document.getElementById('cmb'+b.dataset.cmsg);bx.classList.toggle('hide');if(!bx.classList.contains('hide'))document.getElementById('cmt'+b.dataset.cmsg).focus();return}
 if(b.dataset.csend){var tx=document.getElementById('cmt'+b.dataset.csend).value.trim();if(!tx)return;b.disabled=true;return api('car_msg',{id:+b.dataset.csend,text:tx}).then(function(){b.textContent='Sent ✓';setTimeout(load,900)}).catch(function(e){b.disabled=false;alert(e.message)})}
 if(b.dataset.cno){var why=prompt('Not suitable. Message to send them (optional):','Thanks for sending your car! We could not use this photo. Try a clear side-on photo with the whole car in.');if(why===null)return;return api('car_no',{id:+b.dataset.cno,text:why}).then(load)}
 if(b.dataset.cdel){if(confirm('Delete this car?'))api('car_del',{id:+b.dataset.cdel}).then(load);return}
 if(b.dataset.done)return api('rec_done',{id:+b.dataset.done,undo:b.dataset.u==='1'}).then(load);
 if(b.dataset.del){if(confirm('Delete this recommendation?'))api('rec_del',{id:+b.dataset.del}).then(load);return}
 if(b.dataset.sd){if(confirm('Remove this score?'))api('score_del',{id:+b.dataset.sd}).then(load)}});
load();loadToday();loadStats();setInterval(function(){load();if(V==='stats'){loadToday();loadStats()}},60000);
</script></body></html>
